  DateTime at;
  bool read;

  /// JSON for the API. Server-assigned fields are left out.
  Map<String, dynamic> toJson() => {
        'id': id,
        'title': title,
        'body': body,
        'at': at.toUtc().toIso8601String(),
        'read': read,
      };

  AppNotification copy() => AppNotification.fromJson({...toJson(), });

  @override
  bool operator ==(Object other) => other is AppNotification && other.id == id;

  @override
  int get hashCode => id.hashCode;
}
